            ref={rootRef}
            defaultOpen={defaultOpen}
            open={open}
            onOpenChange={onOpenChange}
            className={cn(CANVAS, layout === "topbar" && "md:bg-sidebar")}
          >
            <ShellFrame
              layout={layout}
              collapsible={collapsible}
              rootRef={rootRef}
              {...shell}
            />
          </SidebarProvider>
        </ShellLayoutProvider>
      </LayoutReserveProvider>
    </HeaderActionsSlotProvider>
  );
